<?php

namespace Doctrine\Tests\ORM\Functional;
use Doctrine\ORM\NonUniqueResultException;
use Doctrine\ORM\Query\QueryException;
use Doctrine\ORM\UnexpectedResultException;
use Doctrine\Tests\Models\CMS\CmsUser,
    Doctrine\Tests\Models\CMS\CmsArticle,
    Doctrine\Tests\Models\CMS\CmsPhonenumber;
use Doctrine\ORM\Mapping\ClassMetadata;
use Doctrine\ORM\Query;
use Doctrine\ORM\Query\Parameter;
use Doctrine\Tests\OrmFunctionalTestCase;

/**
 * Functional tests for the Class Table Inheritance mapping strategy.
 *
 * @author robo
 */
class ClassTableInheritanceTest2 extends OrmFunctionalTestCase
{
    protected function setUp()
    {
        $this->useModelSet('cms');
        parent::setUp();
            $this->_schemaTool->createSchema(array(
                $this->_em->getClassMetadata('Doctrine\Tests\ORM\Functional\CTIParent'),
                $this->_em->getClassMetadata('Doctrine\Tests\ORM\Functional\CTIGChild'),
            ));
    }

    public function testManyToOneInBase()
    {
        $user = new CmsUser;
        $user->name = 'Guilherme';
        $user->username = 'gblanco';
        $user->status = 'developer';

        $child = new CTIGChild;
        $child->setData('child');
    $child->setUser($user);

        $this->_em->persist($child);
        $this->_em->persist($user);

        $this->_em->flush();
        $this->_em->clear();

        $queryBuilder = $this->_em->getRepository('Doctrine\Tests\ORM\Functional\CTIGChild')
                    ->createQueryBuilder('child')
                    ->select('user.id, child.data')
                    ->innerJoin('child.user', 'user')
                    ->where('user.id = 1')
                    ->setMaxResults(1);

        $result = $queryBuilder->getQuery()->getResult();

        $this->assertEquals(1, count($result));
    }

}

/**
 * @Entity @Table(name="cti_parents")
 * @InheritanceType("JOINED")
 * @DiscriminatorColumn(name="type", type="string")
 * @DiscriminatorMap({"parent" = "CTIParent", "gchild" = "CTIGChild"})
 */
class CTIParent {
   /**
     * @Id @Column(type="integer")
     * @GeneratedValue(strategy="AUTO")
     */
    private $id;

    /** @ManyToOne(targetEntity="Doctrine\Tests\Models\CMS\CmsUser", inversedBy="users")
     *  @JoinColumn(name="user_id", referencedColumnName="id", onDelete="SET NULL")
     */
    protected $user;

    public function getId() {
        return $this->id;
    }

    public function getUser() {
        return $this->user;
    }

    public function setUser($user) {
        $this->user = $user;
    }
}

/**
 * @Entity @Table(name="cti_gchildren")
 */
class CTIGChild extends CTIChild {

   /**
     * @Column(type="string")
     */
    protected $data;

    public function getData() {
        return $this->data;
    }

    public function setData($data) {
        $this->data = $data;
    }

}


/**
 */
class CTIChild extends CTIParent {

}
